import 'package:flutter/material.dart';

/// Represents a contextual smart suggestion generated by the
/// application. Suggestions can come from various modules (e.g.
/// recommending a trade, prompting to top up your balance, or
/// highlighting a game you might like). Each suggestion includes a
/// title, description, icon and a destination route to take action.
class SuggestionItem {
  final String id;
  final String title;
  final String description;
  final String type;
  final IconData icon;
  final String route;
  final dynamic arguments;

  const SuggestionItem({
    required this.id,
    required this.title,
    required this.description,
    required this.type,
    required this.icon,
    required this.route,
    this.arguments,
  });
}
